---@class CinemachineCameraHelper
CinemachineCameraHelper = class("CinemachineCameraHelper")

function CinemachineCameraHelper:PersonalHomeEnter(finallyRenderCamera)
    self:SetCineMachineCameraActive(true)
    CSCinemachineCameraManager.Get().finallyRenderCamera = finallyRenderCamera
    UIUtil:AddGameobjectComponent(finallyRenderCamera.gameObject, typeof(CS.UnityEngine.EventSystems.PhysicsRaycaster))
end

function CinemachineCameraHelper:PersonalHomeExit()
    self:SetCineMachineCameraActive(false)
    local finallyRenderCamera = CSCinemachineCameraManager:Get().finallyRenderCamera
    if not GameObjectIsNull(finallyRenderCamera)  then
        GameObject.Destroy(finallyRenderCamera.gameObject)
    end
end

function CinemachineCameraHelper:SetCineMachineCameraActive(active)
    CSCinemachineCameraManager.Get():SetCineMachineCameraActive(active)
end
function CinemachineCameraHelper:GetCineMachineCameraDefaultBland()
    return CSCinemachineCameraManager.Get():GetCineMachineCameraDefaultBland()
end
function CinemachineCameraHelper:GetCineMachineCameraDefaultBlandTime()
    return CSCinemachineCameraManager.Get():GetCineMachineCameraDefaultBlandTime()
end

function CinemachineCameraHelper:SwitchCineMachineCameraDefaultBland(style,time)
     CSCinemachineCameraManager.Get():SwitchCineMachineCameraDefaultBland(style)
end
